import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 37 The Westhaven Express","description":"学习 by、until 与时刻表现在时，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 37 The Westhaven Express","description":"学习 by、until 与时刻表现在时，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 by、until 与时刻表现在时，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 36 A chance in a million","link":"/life/english/new-concept/book-3/unit-02/lesson-036"},"next":{"text":"第三册：培养技能 · Lesson 38 The first calendar","link":"/life/english/new-concept/book-3/unit-02/lesson-038"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 36 A chance in a million","link":"/life/english/new-concept/book-3/unit-02/lesson-036"},"next":{"text":"第三册：培养技能 · Lesson 38 The first calendar","link":"/life/english/new-concept/book-3/unit-02/lesson-038"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-037.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-037.md"}'),l={name:"life/english/new-concept/book-3/unit-02/lesson-037.md"};function o(s,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第三册-培养技能-·-lesson-37-the-westhaven-express" tabindex="-1">第三册：培养技能 · Lesson 37 The Westhaven Express <a class="header-anchor" href="#第三册-培养技能-·-lesson-37-the-westhaven-express" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 37 The Westhaven Express&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕列车时刻、赶车和延误，练习区分到达某时刻之前与持续到该时刻。时间介词的细小差别会影响实际行动。学习 by、until 和 before 的边界，用明确时间描述截止要求，同时理解交通时刻表中的现在时并不表示正在发生。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>timetable</td><td>/ˈtaɪmteɪbl/</td><td>n.</td><td>时刻表</td><td>check the timetable</td></tr><tr><td>platform</td><td>/ˈplætfɔːm/</td><td>n.</td><td>站台</td><td>change platforms</td></tr><tr><td>departure</td><td>/dɪˈpɑːtʃə/</td><td>n.</td><td>出发</td><td>the departure time</td></tr><tr><td>delay</td><td>/dɪˈleɪ/</td><td>v.</td><td>延误</td><td>delay a service</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>on time — 按预定时间</li><li>in time for — 来得及参加或赶上</li></ul><h2 id="语法讲解-by、until-与时刻表现在时" tabindex="-1">语法讲解：by、until 与时刻表现在时 <a class="header-anchor" href="#语法讲解-by、until-与时刻表现在时" aria-label="Permalink to &quot;语法讲解：by、until 与时刻表现在时&quot;">​</a></h2><p>by 加时间表示不迟于该时刻，常与完成目标相关；until 表示动作或状态持续到某时刻。not until 表示直到那时才发生，不能与 by 简单互换。before 严格表示在某时间之前，by 通常包含截止点。表示固定时刻表时，一般现在时可以指将来，如 The train leaves at six，但临时个人安排常用现在进行时。写出时间后还应说明是列车离站、上车截止还是人员到达，避免同一数字承担不同事件。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We must reach the platform by six, although the train does not leave until ten past.</p></blockquote><p>我们必须六点前或六点整到站台，虽然列车六点十分才开。</p><p>by six 给到达截止时间；not ... until ten past 给列车最早实际离开时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Wait by six 不表示一直等到六点，持续等待应写 Wait until six；arrive until six 在此也不自然。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 7:20、seven 和 until it opens，做一张三事件时间线，回听是否把 by 和 until 混淆。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The train leaves at 7:20. We should reach the station by seven. If the platform is closed, we will wait in the hall until it opens.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句赶车计划，区分列车时间、个人截止点和等候时间。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>三个时间表达分别控制离站、到达和等候，行为安排清楚。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句最迟几点到站台？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 六点。</p><p><strong>解析：</strong> by six 表示截止时间。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：The office stays open ___ five.（by/until）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> until</p><p><strong>解析：</strong> stays open 表示持续状态。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>时刻表的 The train leaves tomorrow 是否只能理解为现在动作？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> 一般现在时可表示固定时刻安排。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：by、until 与时刻表现在时。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-036">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-038">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(l,[["render",o]]);export{u as __pageData,b as default};
